e width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"2\">\n<td colspan=\"6\"><b>Earth Elemental Sizes</b><br/></td> \n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>80 lb.<br/></td>\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>48,000 lb.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>750 lb.<br/></td>\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>54,000 lb.<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>6,000 lb.<br/></td>\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>60,000 lb.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
INSERT INTO monster VALUES (346,'Elemental','Earth Elemental, Greater',NULL,'Huge','Elemental','Earth, Extraplanar','21d8+105 (199 hp)','-1','30 ft. (6 squares)','20 (-2 size, -1 Dex, +13 natural), touch 7, flat-footed 20','+15','+33','Slam +23 melee (2d10+10)','2 slams +23 melee (2d10+10) 2','15 ft.','15 ft.','Earth mastery, push','Damage reduction 10/-, earth glide, darkvision 60 ft., elemental traits','Fort +17, Ref +6, Will +9','Str 31, Dex 8, Con 21, Int 8, Wis 11, Cha 11','Listen +14, Spot +14',NULL,'Alertness, Awesome Blow, Cleave, Great Cleave, Improved Bull Rush, Improved Sunder, Iron Will, Power Attack',NULL,'Elemental Plane of Earth','Solitary','9','None','Usually neutral','22-23 HD (Huge)','-','Earth Glide (Ex), Earth Mastery (Ex), Push (Ex)','Greater earth elemental; CR 9; Huge elemental (earth, extraplanar); HD 21d8+105; hp 199; Init -1; Spd 30 ft. (6 squares); AC 20 (-2 size, -1 dex, +13 natural), touch 7, flat-footed 20; Base Atk +15; Grp +33; Atk +23 melee (2d10+10, slam); Full Atk +23 2 melee (2d10+10, 2 slams); Space/Reach 15 ft./15 ft.; SA Earth mastery, push; SQ Damage reduction 10/-, earth glide, darkvision 60 ft., elemental traits; AL N; SV Fort +17, Ref +6, Will +9; Str 31, Dex 8, Con 21, Int 8, Wis 11, Cha 11\n\nSkills and Feats: Listen +14, Spot +14; Alertness, Awesome Blow, Cleave, Great Cleave, Improved Bull Rush, Improved Sunder, Iron Will, Power Attack','\n      <div topic=\"Earth Elemental\" level=\"3\"><p><h3>Earth Elemental</h3></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Earth Elemental, Greater</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Huge Elemental (Earth, Extraplanar)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>21d8+105 (199 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>-1<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>30 ft. (6 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>20 (-2 size, -1 Dex, +13 natural), touch 7, flat-footed 20<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+15/+33<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Slam +23 melee (2d10+10)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>2 slams +23 melee (2d10+10) 2<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>15 ft./15 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Earth mastery, push<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Damage reduction 10/-, earth glide, darkvision 60 ft., elemental traits<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +17, Ref +6, Will +9<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 31, Dex 8, Con 21, Int 8, Wis 11, Cha 11<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Listen +14, Spot +14<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Alertness, Awesome Blow, Cleave, Great Cleave, Improved Bull Rush, Improved Sunder, Iron Will, Power Attack<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Elemental Plane of Earth<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>9<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Usually neutral<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>22-23 HD (Huge)<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n</table><p/><p>When summoned to the Material Plane, an earth elemental consists of whatever types of dirt, stones, precious metals, and gems it was conjured from.</p><p>Earth elementals speak Terran but rarely choose to do so.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Though an earth elemental moves slowly, it is a relentless opponent. It can travel though solid ground or stone as easily as humans walk on the earth\'s surface. It cannot swim, however, and must either walk around a body of water or go through the ground under it. An earth elemental can move along the bottom of a body of water but prefers not to.</p><div topic=\"Earth Mastery\" level=\"8\"><p><b>Earth Mastery (Ex):</b> An earth elemental gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the elemental takes a -4 penalty on attack and damage rolls. (These modifiers are not included in the statistics block.)</p>\n</div><div topic=\"Push\" level=\"8\"><p><b>Push (Ex):</b> An earth elemental can start a bull rush maneuver without provoking an attack of opportunity. The combat modifiers given in Earth Mastery, above, also apply to the elemental\'s opposed Strength checks.</p>\n</div><div topic=\"Earth Glide\" level=\"8\"><p><b>Earth Glide (Ex):</b> An earth elemental can glide through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other signs of its presence. A <i>move earth</i> spell cast on an area containing a burrowing earth elemental flings the elemental back 30 feet, stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"2\">\n<td colspan=\"6\"><b>Earth Elemental Sizes</b><br/></td> \n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n<td><b>Elemental</b><br/></td>\n<td><b>Height</b><br/></td>\n<td><b>Weight</b><br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Small<br/></td>\n<td>4 ft.<br/></td>\n<td>80 lb.<br/></td>\n<td>Huge<br/></td>\n<td>32 ft.<br/></td>\n<td>48,000 lb.<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Medium<br/></td>\n<td>8 ft.<br/></td>\n<td>750 lb.<br/></td>\n<td>Greater<br/></td>\n<td>36 ft.<br/></td>\n<td>54,000 lb.<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Large<br/></td>\n<td>16 ft.<br/></td>\n<td>6,000 lb.<br/></td>\n<td>Elder<br/></td>\n<td>40 ft.<br/></td>\n<td>60,000 lb.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersE-F');
INSERT INTO monster VALUES (347,'Elemental','Earth Elemental, Elder',NULL,'Huge','Elemental','Earth, Extraplanar','24d8+120 (228 hp)','-1','30 ft. (6 squares)','22 (-2 size, -1 Dex, +15 natural), touch 7, flat-footed 22','+18','+37','Slam +27 melee (2d10+11/19-20)','slams +27 melee (2d10+11/19-20)','15 ft.','15 ft.','Earth mastery, push','Damage reduction 10/-, earth glide, darkvision 60 ft., elemental traits','Fort +19, Ref +7, Will +10','Str 33, Dex 8, Con 21, Int 10, Wis 11, Cha 11','Listen +29, Spot +29',NULL,'Alertness, Awesome Blow, Cleave, Great Cleave, Improved Bull Rush, Improved Critical (slam), Improved Sunder, Iron Will, Power Attack',NULL,'Elemental Plane of Earth','Solitary','11','None','Usually neutral','25-48 HD (Huge)','-','Earth Glide (Ex), Earth Mastery (Ex), Push (Ex)','Elder earth elemental; CR 11; Huge elemental (earth, extraplanar); HD 24d8+120; hp 228; Init -1; Spd 30 ft. (6 squares); AC 22 (-2 size, -1 dex, +15 natural), touch 7, flat-footed 22; Base Atk +18; Grp +37; Atk +27 melee (2d10+11/19-20, slam); Full Atk +27 melee (2d10+11/19-20, slams); Space/Reach 15 ft./15 ft.; SA Earth mastery, push; SQ Damage reduction 10/-, earth glide, darkvision 60 ft., elemental traits; AL N; SV Fort +19, Ref +7, Will +10; Str 33, Dex 8, Con 21, Int 10, Wis 11, Cha 11\n\nSkills and Feats: Listen +29, Spot +29; Alertness, Awesome Blow, Cleave, Great Cleave, Improved Bull Rush, Improved Critical (slam), Improved Sunder, Iron Will, Power Attack','\n      <div topic=\"Earth Elemental\" level=\"3\"><p><h3>Earth Elemental</h3></p><p/><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td><b>Earth Elemental, Elder</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Huge Elemental (Earth, Extraplanar)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>24d8+120 (228 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" cur